using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "System.Text.Json", "System.Xml",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions", "Newtonsoft",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_depends_on_no_other_layer()
    {
        Assert.Empty(ReferencedLayers(Domain));
    }

    [Fact]
    public void Application_depends_only_on_Domain()
    {
        Assert.Empty(ReferencedLayers(Application).Where(n => n != Domain.GetName().Name));
    }

    [Theory]
    [InlineData("Domain")]
    [InlineData("Application")]
    public void Business_code_does_not_use_technical_details(string layer)
    {
        var assembly = layer == "Domain" ? Domain : Application;
        Assert.Empty(TechnicalTypeReferences(assembly));
    }

    private static IEnumerable<string> ReferencedLayers(Assembly assembly) =>
        assembly.GetReferencedAssemblies()
            .Select(a => a.Name!)
            .Where(n => n.StartsWith("PaymentAuthorization.", StringComparison.Ordinal));

    private static IEnumerable<string> TechnicalTypeReferences(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();
        foreach (var handle in reader.TypeReferences)
        {
            var reference = reader.GetTypeReference(handle);
            var ns = reader.GetString(reference.Namespace);
            if (TechnicalNamespaces.Any(t => ns == t || ns.StartsWith(t + ".", StringComparison.Ordinal)))
                yield return $"{ns}.{reader.GetString(reference.Name)}";
        }
    }
}
